{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slikk_fact_item as WITH sales AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(sku)) END AS sku, UPPER(CASE WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-05- SHIRT\' THEN \'4MSN1310-05\' WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-02-SHIRT\' THEN \'4MSN1310-02\' WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-08-SHIRT\' THEN \'4MSN1310-08\' WHEN upper(sku) LIKE \'4C%\' THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) || \'-\' || SPLIT_PART(sku, \'-\', 3) WHEN POSITION(\'-\' IN sku) > 0 THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) ELSE sku END) AS sku_group, sp::int AS SP, mrp::int AS MRP, tax::int AS TAX, discount::int AS discount, invoice_id, TO_DATE(order_date, \'DD-MM-YYYY\') AS order_date, total_amount::int AS total_amount, payment_status, total_quantity::int AS total_quantity FROM snitch_db.maplemonk.S3_SLIKK_SALES ), returnss AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(sku)) END AS sku, original_invoice_id AS invoice_id, TO_DATE(create_date, \'DD-MM-YYYY\') AS return_date, MAX(status) AS return_status, SUM(quantity::int) AS return_quantity, MAX(return_reason) AS return_reason, MAX(CASE WHEN LOWER(return_reason) LIKE \'%size%\' THEN \'Size & Fit Issue\' WHEN LOWER(return_reason) LIKE \'%quality%\' THEN \'Quality Issue\' WHEN return_reason = \'Return Reason not found\' THEN \'Return Reason not found\' WHEN return_reason LIKE \'Miscellaneous%\' THEN \'Customer Changed Mined\' WHEN return_reason LIKE \'Order and Shipping Issues%\' THEN \'Order and Shipping Issues\' WHEN return_reason LIKE \'Color and Appearance%\' THEN \'Catalog Issues\' ELSE \'Customer Changed Mined\' END) AS Resaons, MAX(return_invoice_id) AS return_invoice_id FROM snitch_db.maplemonk.S3_SLIKK_RETURNS WHERE status != \'CANCELLED\' GROUP BY sku, original_invoice_id, create_date ), latest_metafields AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ), fallback_metafields AS ( SELECT SKU_GROUP, CATEGORY, TITLE, MATERIAL_NEW, PRINT_DESIGN, FIT, SLEEVE_TYPE, COLLAR_NEW FROM snitch_db.maplemonk.GS_MP_SKU_META_SHEET1 QUALIFY ROW_NUMBER() OVER(PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) = 1 ), mp_categories AS ( SELECT DISTINCT REGEXP_REPLACE(SKU, \'-[^-]*$\', \'\') AS sku_group, ANY_VALUE(CATEGORY) AS category FROM snitch_db.maplemonk.LOGIC_FINAL_ITEM_MASTER WHERE SKU LIKE \'MP%\' GROUP BY 1 ) SELECT a.sku, a.sku_group, SPLIT_PART(a.sku, \'-\', 3) AS size, a.sp, a.mrp, a.tax, a.discount, a.invoice_id, a.order_date, a.total_amount, a.payment_status, a.total_quantity, b.return_date, b.return_status, b.return_quantity, b.return_reason, b.Resaons, b.return_invoice_id, m.product_name, m.sku_class, INITCAP(COALESCE(mpc.category, m.category, fb.CATEGORY)) AS category, COALESCE(m.title, fb.TITLE) AS title, COALESCE(m.print_design, fb.PRINT_DESIGN) AS print_design, COALESCE(m.collar_new, fb.COLLAR_NEW) AS collar_new, COALESCE(m.material_new, fb.MATERIAL_NEW) AS material_new, COALESCE(m.fit, fb.FIT) AS fit, m.color, COALESCE(m.sleeve_type, fb.SLEEVE_TYPE) AS sleeve_type FROM sales a LEFT JOIN returnss b ON a.invoice_id = b.invoice_id AND a.sku = b.sku LEFT JOIN latest_metafields m ON a.sku_group = m.sku_group LEFT JOIN mp_categories mpc ON a.sku_group = mpc.sku_group LEFT JOIN fallback_metafields fb ON a.sku_group = fb.SKU_GROUP;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            